def play_tic_tac_toe():
    """
    Implements a simple Tic-Tac-Toe game.
    """

    # Initialize the game board as a 3x3 list of empty strings
    game_board = [[' '] * 3 for _ in range(3)]

    def print_board():
        """
        Prints the current game board.
        """
        for row in game_board:
            print(' | '.join(row))
            print('-' * 9)

    def get_user_move():
        """
        Gets a valid user move (row and column).
        """
        while True:
            try:
                row, col = map(int, input("Enter your move (row, col): ").split())
                if 0 < row <= 3 and 0 < col <= 3 and game_board[row - 1][col - 1] == ' ':
                    return row - 1, col - 1
                else:
                    print("Invalid move. Please enter a number between 1 and 3.")
            except ValueError:
                print("Invalid input. Please enter two numbers separated by a space.")

    def check_winner():
        """
        Checks for a winner.
        """
        for row in game_board:
            if row[0] != ' ' or row[1] != ' ' or row[2] != ' ':
                if row[0] == row[1] == row[2]:
                    return row[0], True

        for col in range(3):
            if game_board[0][col] != ' ' or game_board[1][col] != ' ' or game_board[2][col] != ' ':
                if game_board[0][col] == game_board[1][col] == game_board[2][col]:
                    return game_board[0][col], True

        if game_board[0][0] != ' ' or game_board[1][1] != ' ' or game_board[2][2] != ' ':
            if game_board[0][0] == game_board[1][1] == game_board[2][2]:
                return game_board[0][0], True

        if game_board[0][2] != ' ' or game_board[1][1] != ' ' or game_board[2][0] != ' ':
            if game_board[0][2] == game_board[1][1] == game_board[2][0]:
                return game_board[0][2], True

        return None, False

    while True:
        print_board()
        row, col = get_user_move()
        game_board[row][col] = 'X'

        winner, game_over = check_winner()

        if winner:
            print_board()
            print(f"Congratulations! Player 'X' wins!")
            break
        elif game_over:
            print_board()
            print("It's a tie!")
            break


if __name__ == "__main__":
    play_tic_tac_toe()
